import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../../types";
import { BargeInEvent } from "./BargeInEvent";

const event: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.UserBargeIn,
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    parseData: {},
    playback: {
      acknowledged_intermediate_markers: [{ kind: "audio_elapsed", offset_ms: 2000 }],
      total_audio_duration_ms: 8400,
    },
  },
};

describe("BargeInEvent", () => {
  it("shows the confirmed playback progress", () => {
    renderWithProviders(<BargeInEvent event={event} isSelected={false} />);

    expect(
      screen.getByText("User interrupted playback · Confirmed through 2.0 s of 8.4 s (24%)"),
    ).toBeInTheDocument();
  });

  it("shows the interrupted word and its position", () => {
    const eventAtWord: ConversationEvent = {
      ...event,
      metadata: {
        parseData: {},
        playback: {
          acknowledged_intermediate_markers: [
            { kind: "word", word_index: 58, offset_ms: 4200 },
            { kind: "audio_elapsed", offset_ms: 5000 },
          ],
          interrupted_word: "transactions.",
          interrupted_word_index: 58,
          response_word_count: 105,
          total_audio_duration_ms: 8400,
        },
      },
    };

    renderWithProviders(<BargeInEvent event={eventAtWord} isSelected={false} />);

    expect(
      screen.getByText(
        'User interrupted playback · Interrupted at "transactions." (word 59 of 105)',
      ),
    ).toBeInTheDocument();
  });

  it("shows a fallback when metadata has no playback key", () => {
    const eventWithoutPlayback: ConversationEvent = {
      ...event,
      metadata: { parseData: {} },
    };

    renderWithProviders(<BargeInEvent event={eventWithoutPlayback} isSelected={false} />);

    expect(
      screen.getByText("User interrupted playback · Playback position unavailable"),
    ).toBeInTheDocument();
  });
});
